#!/usr/bin/env bash
# GENERATED by plugin-cursor/scripts/compose.sh — edit core/ or plugin-claude/ then re-compose
# Copyright (c) 2024-2026 H3Tech Inc. All rights reserved. PROPRIETARY.
#
# Background monitor: tail the synaptory events JSONL and emit a notification
# line for each notable event. Claude Code delivers each stdout line as a
# push notification during the session.
#
# Notable events surfaced (matched against the events story_pipeline.py /
# the hooks actually emit — see synaptory_logger.py):
#   depth_guard_blocked          — agent delegation depth exceeded, spawn refused
#   transition (to_state=blocked) — a story was blocked (gate/dependency/retry)
#   dod_evaluated (passed=false) — a DoD evaluation failed a required gate
#   loop_guard_trip              — P2 loop engine stopped a no-progress loop
#
# This script runs continuously (monitors are persistent processes). It exits
# cleanly when the events file disappears (project closed / workspace cleared).

set -u

_HOOK_ROOT="${PLUGIN_ROOT:-$(cd "$(dirname "$0")/.." && pwd)}"
source "${_HOOK_ROOT}/hooks/lib/resolve-python.sh" 2>/dev/null || exit 0
_py="${SYNAPTORY_PYTHON:-python3}"

# Resolve the project dir. Monitors inherit the session's environment, so
# CLAUDE_PROJECT_DIR is the primary source; fall back to $PWD (monitors are
# spawned with the project as cwd). If neither points at a real directory,
# exit quietly — not a synaptory project session.
_project_dir="${CLAUDE_PROJECT_DIR:-$PWD}"
if [ -z "$_project_dir" ] || [ ! -d "$_project_dir" ]; then
  exit 0
fi

EVENTS_FILE="${_project_dir}/.synaptory/.orchestrator/events.jsonl"

# Wait for the events file to appear (it's created on first event).
_waited=0
while [ ! -f "$EVENTS_FILE" ]; do
  sleep 2
  _waited=$((_waited + 2))
  if [ "$_waited" -gt 30 ]; then
    # No .synaptory workspace after 30s — not a synaptory project.
    exit 0
  fi
done

# Tail the file and emit formatted notifications.
tail -F "$EVENTS_FILE" 2>/dev/null | "$_py" -u -c "
import sys, json

for raw in sys.stdin:
    raw = raw.strip()
    if not raw:
        continue
    try:
        ev = json.loads(raw)
    except Exception:
        continue
    t = (ev.get('event_type') or ev.get('event') or '').strip()
    # synaptory_logger writes every payload key at the TOP LEVEL of the
    # record (both the Python emit() and the key=value CLI form) — there is
    # no 'extra' envelope. Read top-level, falling back to a legacy 'extra'
    # only defensively.
    extra = ev.get('extra') or {}
    def g(key, default=''):
        v = ev.get(key)
        return v if v is not None else extra.get(key, default)
    story = g('story_id')

    # The pipeline emits generic 'transition' / 'dod_evaluated' events (see
    # story_pipeline.py) — NOT 'story_blocked' / 'dod_gate_failed'. Match the
    # events that actually fire and filter to the notable cases.
    if t == 'depth_guard_blocked':
        print(f'[synaptory] ⛔ Agent spawn blocked: delegation depth '
              f\"{g('attempted_depth', '?')} > max {g('max', '3')}. \"
              f'Check .synaptory/.orchestrator/events.jsonl for the call chain.')
        sys.stdout.flush()

    elif t == 'transition' and g('to_state') == 'blocked':
        reason = g('reason')
        label  = f'Story {story}' if story else 'A story'
        print(f'[synaptory] ⚠️ {label} is BLOCKED: {reason}')
        sys.stdout.flush()

    elif t == 'dod_evaluated' and g('passed') is False:
        failed = g('failed_required', []) or []
        gates = ', '.join(failed) if isinstance(failed, list) else str(failed)
        label = f'Story {story}' if story else 'a story'
        print(f'[synaptory] 🚫 DoD gate failed for {label}'
              + (f' — unmet: {gates}' if gates else ''))
        sys.stdout.flush()

    elif t == 'loop_guard_trip':
        # Emitted by the P2 loop engine (epic #75) when the continuation
        # loop stops itself for lack of progress.
        print(f'[synaptory] 🔁 Loop guard tripped: {g(\"reason\", \"no progress across continuations\")}')
        sys.stdout.flush()
" 2>/dev/null

exit 0
